use vstd::prelude::*;

verus! {

fn solve(a: i8, b: i8, f: i8, k: i8) -> (res: i8)
    // We only call solve with non‐negative parameters (so that casts to i16 are safe)
    requires
        0 <= a,
        0 <= b,
        0 <= f,
        f <= a,
        0 <= k,
    // The code always returns exactly –1, 0, or 1
    ensures
        res == -1 || res == 0 || res == 1,
{
    // Promote to i16 for the arithmetic in the loop
    let a = a as i16;
    let b = b as i16;
    let f = f as i16;
    let k = k as i16;

    let mut cur_pos: i16 = 0;       // current endpoint (0 or a)
    let mut fuel: i16    = b;       // fuel in tank, always between 0 and b
    let mut refuels: i16 = 0;       // how many times we topped up
    let mut leg: i16     = 0;       // how many legs we have done

    while leg < k
        invariant
            // leg is between 0 and k
            0 <= leg && leg <= k,
            // position is always at one of the two endpoints
            (cur_pos == 0) || (cur_pos == a),
            // fuel is never negative and never exceeds capacity b
            0 <= fuel && fuel <= b,
            // we never refuel more than the number of legs already taken
            0 <= refuels && refuels <= leg,
        decreases k - leg,
    {
        leg = leg + 1;

        // figure out station position this leg and the destination endpoint
        let (station_pos, dest) =
            if cur_pos == 0 {
                (f, a)
            } else {
                (a - f, 0)
            };
        // both station_pos and dest must lie in [0..=a]
        assert(0 <= station_pos && station_pos <= a);
        assert(0 <= dest        && dest        <= a);

        // 1) drive from cur_pos to station_pos
        let d1 = (station_pos - cur_pos).abs();
        assert(0 <= d1 && d1 <= a);
        if fuel < d1 {
            // we can't even reach the station
            return -1;
        }
        fuel    = fuel - d1;
        cur_pos = station_pos;

        // 2) now compute how far from station → dest, plus if there is a next leg
        let d2 = (dest - station_pos).abs();
        assert(0 <= d2 && d2 <= a);
        let d3 =
            if leg < k {
                // next leg will go back, so the next station is either f or a-f
                let next_station = if dest == 0 { f } else { a - f };
                let dd = (next_station - dest).abs();
                assert(0 <= dd && dd <= a);
                dd
            } else {
                0
            };
        let needed = d2 + d3;
        assert(needed >= 0);

        // if we don't have enough fuel for station→dest and then on to the next station,
        // we refuel here (if we can)
        if fuel < needed {
            refuels = refuels + 1;
            fuel    = b;
            if fuel < needed {
                return -1;
            }
        }

        // 3) actually drive to dest
        fuel    = fuel - d2;
        cur_pos = dest;
    }

    // at the end, return 0 if we never refueled, else 1
    if refuels == 0 { 0 } else { 1 }
}

} // end verus!

